type RowProps<T extends ElementType = 'div'> = PrimitiveProps<T> & {
  label?: ReactNode
  /** Second line under `label`, in the secondary colour. Most iOS rows have one. */
  subtitle?: ReactNode
  detail?: ReactNode
  icon?: ReactNode
  chevron?: boolean
}

type WidgetProps = {
  snapshot: WidgetSnapshot
  updatedAt: number
  onOpen: (element: HTMLElement, arg?: string) => void
}
